INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kaboom', 12309, '1981-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co97gr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpzk4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaboom!', 'Kaboom! is an unauthorized adaptation of the 1978 Atari coin-op Avalanche. The gameplay of both games is fundamentally the same, but Kaboom! was re-themed to be about a mad bomber instead of falling rocks. Gameplay in Kaboom! consists of using a paddle controller to catch bombs dropped by the Mad Bomber with a set of three buckets. Points are scored for every bomb caught, extra buckets (maximum of three) are awarded at every 1,000 points, and one bucket is lost every time a bomb is missed. As the game progresses, the "Mad Bomber" traverses the top of the screen much more erratically, dropping bombs at increasingly higher speeds, making each of the seven higher levels more difficult.' FROM games WHERE igdb_id = 12309 ON CONFLICT (game_id, language_code) DO NOTHING;
