INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('centipede', 2235, '1981-06-06', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8wem.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8vf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Centipede', 'Centipede is a vertically-oriented shoot ''em up arcade game produced by Atari, Inc. in 1980. The game was designed by Ed Logg along with Dona Bailey, one of the few female game programmers in the industry at this time. It was also the first arcade coin-operated game to have a significant female player base. The player defends against swarms of insects, completing a round after eliminating the centipede that winds down the playing field.' FROM games WHERE igdb_id = 2235 ON CONFLICT (game_id, language_code) DO NOTHING;
