INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lock-n-chase', 22717, '1981-06-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3tmu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar13hs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lock ''n'' Chase', 'Lock ''n'' Chase is a 1981 maze arcade game developed and published by Data East in Japan in 1981, and later published in North America by Taito. Lock ''n'' Chase was Data East''s response to Pac-Man. The game''s main character is a thief. The object of the game is to enter a maze and collect all the coins and, if possible, any other treasure that may appear. The thief must then exit the maze (a vault) without being apprehended by the Super D (policemen). The thief can close doorways within the maze in order to temporarily trap the Super D and allow him to keep his distance from them. Only two doors can be closed at a time. The Super D policemen are named Stiffy, Scaredy, Smarty, and Silly.' FROM games WHERE igdb_id = 22717 ON CONFLICT (game_id, language_code) DO NOTHING;
