INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tennis', 'Tennis offers singles matches for one or two players; one player is colored pink, the other blue. The game has two user-selectable speed levels. When serving and returning shots, the tennis players automatically swing forehand or backhand as the situation demands, and all shots automatically clear the net and land in bounds. The first player to win one six-game set is declared the winner of the match (if the set ends in a 6-6 tie, the set restarts from 0-0). This differs from professional tennis, in which player must win at least two out of three six-game sets.' FROM games WHERE igdb_id = 64208 ON CONFLICT (game_id, language_code) DO NOTHING;
