INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PBA Bowling', 'Get your ball and rack up the pins, as one of America''s favorite sports makes its Windows 95 debut in PBA Bowling. The official computer game of the Professional Bowlers Association, PBA Bowling brings the excitement of one of America''s best-loved pastimes to your PC. With a realistic physics model, digitized players and full-motion video, you''ll think it''s Friday night at the local lanes!.' FROM games WHERE igdb_id = 15507 ON CONFLICT (game_id, language_code) DO NOTHING;
