INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Cobra', 'You''re a helicopter gunship pilot on a daring and dangerous mission: air surveillance of enemy territory. Success depends on how far you can penetrate enemy airspace. Can you handle the pressure? Because the further you go, the more difficult the mission becomes. Show that you''ve got what it takes by maneuvering your chopper around craggy mountain peaks, through deep dark tunnels, and over tall city buildings. All while you face enemy tanks and missiles and weird sky-flying weapons. But you can fight back with high-flying, quick-thinking, fast-reaction moves. Good luck and good flying!' FROM games WHERE igdb_id = 5708 ON CONFLICT (game_id, language_code) DO NOTHING;
