INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lady Bug', 'Lady Bug is an insect-themed maze chase arcade game produced by Universal Entertainment Corporation and released in 1981. Its gameplay is similar to Pac-Man, with the primary addition to the formula being gates that change the layout of the maze when used. The arcade original was relatively obscure, but the game found wider recognition and success as a launch title for the ColecoVision console.' FROM games WHERE igdb_id = 5677 ON CONFLICT (game_id, language_code) DO NOTHING;
