INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'New Rally-X', 'New Rally-X is a maze and driving arcade game that was released by Namco in 1981. It runs on similar hardware to that of its predecessor, and as its name suggests, it is a revised version of that title, which was released in the previous year. The only differences are that it has slightly enhanced graphics, easier gameplay, a new soundtrack, and a "Lucky Flag" (with the letter "L") that gives the player extra points for remaining fuel when collected, after which the round will continue if there are still flags remaining. The mazes are mostly identical, with some of the blocks from Rally-X changed into roads to reduce dead ends, and some different flag (and rock) locations. This title was manufactured in greater numbers and was much more popular in Japan than its predecessor.' FROM games WHERE igdb_id = 18621 ON CONFLICT (game_id, language_code) DO NOTHING;
