INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('laser-blast', 18034, '1981-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9iuu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpnq7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laser Blast', 'The object of Laser Blast is to destroy a series of land-based enemies. The player controls a fleet of flying saucers, operating one at a time. On the planet surface below are a group of three mobile laser bases, guarded by an invisible force field that prevents the player''s saucer from getting too close to the surface. Both the player and the enemy bases are armed with laser blasters, which may fire a single continuous beam at a time. If the player''s saucer is hit, it will lose altitude and crash to the ground; however, the player may direct this fall, potentially into one of the bases, destroying it as well. Each succeeding wave of enemy bases moves faster and targets the player''s saucers more quickly, while the force field becomes stronger and decreases the amount of space in which the saucer can move. Players score points for each base destroyed, with points multiplying each wave up to a maximum of 90 points per base. Players earn extra flying saucers with each 1000 points scored and may keep a maximum of six extra saucers in reserve. When the score of 999,999 is reached, the digits in the score turn to exclamation points, and the game ends.' FROM games WHERE igdb_id = 18034 ON CONFLICT (game_id, language_code) DO NOTHING;
