INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zork-ii-the-wizard-of-frobozz', 1945, '1981-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zgc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvly.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zork II: The Wizard of Frobozz', 'The adventure begins in the Barrow from "Zork I" armed only with the trusty brass lantern and sword of elvish antiquity. The purpose of the game is not initially clear. Like its predecessor, Zork II is essentially a treasure hunt. Unlike the previous game, the ten treasures are tied together by a crude plot. Finding the treasures does not end the game, nor are all the treasures needed to finish the game. Instead, the adventurer must figure out a way to use the treasures in order to reach the game''s finale.' FROM games WHERE igdb_id = 1945 ON CONFLICT (game_id, language_code) DO NOTHING;
