INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Strike', 'Launching from repair bay 28 of the Galatea, you guide your Blue Fighter Wing through the Launch Ring at lightspeed, entering enemy territory, sector Delta Five Niner! Your mission: Rescue the Orange Wing Center which was captured alive, before the enemy ingests his brain -- A brain which they consider to not only be an excellent source of protein, but also, once consumed, transfers all knowledge to the species - Including military secrets, vital to the survival of all mankind! Can you rescue your comrad & Destroy the opposing Protoid Forces?' FROM games WHERE igdb_id = 5705 ON CONFLICT (game_id, language_code) DO NOTHING;
