INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Omega Race', 'Set in the year 2003, the game involves using a spaceship to destroy enemy droid ships. The player''s ship is controlled with a spinner to rotate the ship, a button for thrusting, and a button for firing lasers. The enemies that the player must destroy or avoid are drone ships, commander ships, two types of space mines, and shooting star ships. The ship bounces off an invisible barrier on the edges of the screen that briefly appears when hit. By default, Extra ships are awarded at 40,000 and 100,000 points, but this can be changed by the machine''s owner.' FROM games WHERE igdb_id = 18562 ON CONFLICT (game_id, language_code) DO NOTHING;
