INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('astro-blaster', 13959, '1981-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wkk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmltl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astro Blaster', 'The player controls a ship (bearing a resemblance to the Battlestar Galactica) which can fire and move left or right. The player must continuously monitor the onscreen temperature and fuel gauges; if the ship overheats, its weapon is disabled, and if it is depleted of fuel, the vessel itself explodes. The player must battle through waves of enemies, which attack with varied formations and flight patterns. When a wave is destroyed, a new one appears. At the end of each sector, the player flies through an asteroid belt and can obtain extra fuel by shooting fireballs. After this, the mother ship is met, where the player docks and refuels for the next sector. Also, the player is rewarded various bonuses for accomplishing certain feats, such as, shooting all enemies in a specific order or shooting all enemies without missing.' FROM games WHERE igdb_id = 13959 ON CONFLICT (game_id, language_code) DO NOTHING;
