INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Magic', 'Midnight Magic utilized the Atari 2600 joystick for performing simulated pinball functions, such as activating the flippers and shooting the ball. Moving the joystick controller down pulls the pinball machine plunger back while pressing the joystick button shoots the ball into the playfield. The left and right flippers are activated by moving the joystick controller left or right. Hitting all five drop targets at the top of the table increases the bonus multiplier (2x, 3x, and so on). Extra balls can be earned when hitting the rollover targets at the top left and right corners of the table when the bonus multiplier is activated.' FROM games WHERE igdb_id = 41109 ON CONFLICT (game_id, language_code) DO NOTHING;
