INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '5', '005 is a 1981 arcade game by Sega, in which the player''s mission is to take a briefcase of secret documents to a waiting helicopter. It is one of the first examples of a stealth game. The player controls a spy who must avoid the enemies as he makes his way through buildings and warehouses, where he will have to dodge the enemies'' flashlights and use boxes as hiding spots.' FROM games WHERE igdb_id = 38521 ON CONFLICT (game_id, language_code) DO NOTHING;
