INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('defender', 3873, '1981-03-01', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7qsm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sca578.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Defender', 'Defender is an arcade video game developed released by Williams Electronics in 1980. A shooting game featuring two-dimensional (2D) graphics, the game is set on a fictional planet where the player must defeat waves of invading aliens while protecting astronauts. Development was led by Eugene Jarvis, a pinball programmer at Williams; Defender was Jarvis''s first video game project, and drew inspiration from Space Invaders and Asteroids. Williams planned to display the game at the Amusement & Music Operators Association (AMOA) trade show, though development delays resulted in the team working on the game up until the show started. Defender was commercially successful, selling over 55,000 units to become the company''s best selling arcade game. Praise among critics focused on the game''s audio-visuals and gameplay. It is frequently listed as one of Jarvis''s best contributions to the video game industry, as well as one of the most difficult video games. Defender was ported to numerous platforms, inspired the development of other games, and was followed by sequels and many imitations.' FROM games WHERE igdb_id = 3873 ON CONFLICT (game_id, language_code) DO NOTHING;
