INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bosconian', 18758, '1981-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2top.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq1on.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bosconian', 'The object of Bosconian is to score as many points as possible by destroying enemy bases and ships. The player controls a small fighter ship that can move in eight directions and can fire both forward and backward. Each level consists of a number of green space stations that must all be destroyed to advance to the next level (a semi-transparent mini-map helps identify their location). Each station consists of six cannons arranged in a hexagon, surrounding a central core. The player must either destroy all six cannons or shoot the core to destroy a station, and in later levels the core is capable of defending itself. Additionally, the player must avoid or destroy asteroids, mines, and a variety of enemy missiles and ships that attempt to collide with the player''s ship. Enemies occasionally launch formation attacks — destroying the leader causes all remaining enemies to disperse, but destroying all enemies in a formation scores extra bonus points. A spy ship (worth a random bonus value) also appears occasionally, which must be destroyed or the enemies will go berserk.' FROM games WHERE igdb_id = 18758 ON CONFLICT (game_id, language_code) DO NOTHING;
