INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultima', 'Ultima (later titled, Ultima: The First Age of Darkness) is the first game in the Ultima series of role-playing video games created by Richard Garriott. The game was one of the first definitive commercial computer RPGs, and is considered an important and influential turning point for the development of the genre throughout years to come.' FROM games WHERE igdb_id = 7414 ON CONFLICT (game_id, language_code) DO NOTHING;
