INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('astrosmash', 5657, '1981-10-15', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wva.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sccs8z.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astrosmash', 'In Astrosmash you control a laser canon at the bottom of the screen; your goal is to earn as many points as possible by destroying the various incoming meteors, bombs, and other objects. Points are earned for destroying objects, while points are lost for letting them get past you. Meteors are the most common item you need to defend yourself against. They come in various sizes and colors, and some even split into two smaller meteors when shot. Mixed in with the meteors are white spinning bombs. While letting a meteor get past you will only lower your score, you have to shoot the spinners. If one gets past, you will lose a life. On the more difficult levels, ufo''s and guided missiles will also appear occasionally and attempt to destroy your canon.' FROM games WHERE igdb_id = 5657 ON CONFLICT (game_id, language_code) DO NOTHING;
