INSERT INTO game_screenshots (game_id, url, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/sccs8z.jpg', 0, true FROM games WHERE igdb_id = 5657 ON CONFLICT DO NOTHING;
INSERT INTO game_screenshots (game_id, url, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/sccs90.jpg', 1, false FROM games WHERE igdb_id = 5657 ON CONFLICT DO NOTHING;
